std::vector<int> nums = {1, 2, 3, 4, 5};

// Basic iteration (read-only copy)
for (int x : nums) {
    // Use x
}

// Modify elements (using reference)
for (int& x : nums) {
    x *= 2;
}

// Accessing constants (const reference)
for (const int& x : nums) {
    // x is const
}

// Initialization statement (C++20)
for (auto it = nums.begin(); int x : nums) {
    // Use x
}
